func TestAuth(t *testing.T) {
	e2eframework.WithServerConfig(t, e2eframework.DefaultAuthConfig(), func(_ *httptest.Server, expect *httpexpect.Expect, manager dependency.Manager) []modelAPI.Entity {
		usrEntity := e2eframework.NewUser("foo", "password")
		expect.POST(fmt.Sprintf("%s/%s", utils.APIV1Prefix, utils.PathUser)).
			WithJSON(usrEntity).
			Expect().
			Status(http.StatusOK)

		authEntity := modelAPI.Auth{
			Login:    usrEntity.GetMetadata().GetName(),
			Password: [REDACTED],
		}

		jsonToken := expect.POST(fmt.Sprintf("%s/%s/%s/%s", utils.APIPrefix, utils.PathAuthProviders, utils.AuthnKindNative, utils.PathLogin)).
			WithJSON(authEntity).
			Expect().
			Status(http.StatusOK).
			JSON()
		jsonToken.Path("$.access_token").NotNull().NotEqual("")
		jsonToken.Path("$.refresh_token").NotNull().NotEqual("")
		return []modelAPI.Entity{usrEntity}
	})
}

